      intro: "Cor.股份有限公司（以下简称“本公司”）充分认识到本公司所处理的个人信息的重要性，依据《个人信息保护法》（以下简称“个人信息保护法”）及其他相关法令、指南，以及基于ISO/IEC 27001:2022（JIS Q 27001:2023）的信息安全管理体系，妥善处理客户、员工、应聘者及其他各位的个人信息。本公司依据以下方针保护个人信息。",
      businessTitle: "1. 企业信息",
